# Brute-force cross-check with an independently written matcher.
MONTHS = {n: i + 1 for i, n in enumerate(
    ["JAN", "FEB", "MAR", "APR", "MAY", "JUN", "JUL", "AUG", "SEP", "OCT", "NOV", "DEC"])}
DOWS = {n: i for i, n in enumerate(["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"])}


def _value(tok, low, high, names):
    if names and tok.upper() in names:
        return names[tok.upper()]
    assert tok.isdigit(), tok
    v = int(tok)
    assert low <= v <= high, tok
    return v


def _field(text, low, high, names=None):
    out = set()
    for item in text.split(","):
        base, _, step = item.partition("/")
        step = int(step) if step else 1
        if base == "*":
            a, b = low, high
        elif "-" in base:
            x, y = base.split("-")
            a, b = _value(x, low, high, names), _value(y, low, high, names)
        else:
            a = _value(base, low, high, names)
            b = high if "/" in item else a
        out.update(range(a, b + 1, step))
    return out


def brute_match(expr, t):
    mi, ho, dom, mo, dow = expr.split()
    if not (t.minute in _field(mi, 0, 59) and t.hour in _field(ho, 0, 23)
            and t.month in _field(mo, 1, 12, MONTHS)):
        return False
    dmatches = t.day in _field(dom, 1, 31)
    wmatches = ((t.weekday() + 1) % 7) in _field(dow, 0, 7, DOWS)
    if dom != "*" and dow != "*":
        return dmatches or wmatches
    return dmatches and wmatches


def brute(expr, after, limit_days=400):
    t = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    end = after + timedelta(days=limit_days)
    while t <= end:
        if brute_match(expr, t):
            return t
        t += timedelta(minutes=1)
    return None

