    ("0 12 1,15 * *", dt(2024, 1, 10)),
    ("*/30 * 1,15 * 0", dt(2024, 1, 1)),
]
for expr, after in random_cases:
    check(f"cron brute {expr} @ {after}", lambda e=expr, a=after: (
